const STANDALONE_UI_RUNTIME=`(()=>{const fullscreenButton=document.getElementById('fullscreen');fullscreenButton&&fullscreenButton.remove();const payloadNode=document.getElementById('lorana-performance'),coachNode=document.getElementById('coach'),coachText=coachNode&&coachNode.querySelector('span');try{const payload=JSON.parse(payloadNode.textContent||'{}');if(coachText)coachText.textContent=payload.settings&&payload.settings.autoplay?'点击画布可以下一句，自动播放状态下也可以哦~':'这个演出没有开启自动播放，请点击画布播放下一句。'}catch{}const stageNode=document.getElementById('stage'),counterNode=document.getElementById('counter');if(!stageNode||!counterNode)return;const notice=document.createElement('div');notice.className='playback-complete-notice';notice.textContent='播放完成';notice.hidden=true;notice.setAttribute('role','status');document.body.append(notice);let settleTimer=0,hideTimer=0,shownForEnd=false;const check=()=>{clearTimeout(settleTimer);const parts=(counterNode.textContent||'').split('/').map(value=>Number(value.trim()));const complete=parts.length===2&&parts[1]>0&&parts[0]>=parts[1];if(!complete){shownForEnd=false;notice.hidden=true;return}if(shownForEnd)return;settleTimer=setTimeout(()=>{const latest=(counterNode.textContent||'').split('/').map(value=>Number(value.trim()));if(latest.length!==2||latest[1]<=0||latest[0]<latest[1])return;shownForEnd=true;notice.hidden=false;clearTimeout(hideTimer);hideTimer=setTimeout(()=>{notice.hidden=true},1400)},650)};new MutationObserver(check).observe(stageNode,{childList:true,subtree:true,characterData:true});new MutationObserver(check).observe(counterNode,{childList:true,subtree:true,characterData:true})})();`;

async function resolvePool<T>(items:T[],worker:(item:T)=>Promise<void>,concurrency=4){let cursor=0;await Promise.all(Array.from({length:Math.min(concurrency,items.length)},async()=>{while(cursor<items.length){const item=items[cursor++];await worker(item)}}))}

export async function createPerformanceHtml(archive:StoryArchive,resolveAsset:Resolver,resolveAvatar:(character:StoryCharacter)=>Promise<string>,embeddedVfx:Record<string,string>={}):Promise<string>{
  archive=archiveForSignedExport(archive);
  const assetData:Record<string,string>={};const refs=new Map<string,StoryAssetRef>();
  for(const message of archive.document.messages)if(message.kind!=="text")refs.set(message.asset.id,message.asset);
  const faceIds=new Set<string>();for(const message of archive.document.messages)if(message.kind==="text")for(const segment of storyTextSegments(message.text,archive.document.characters,archive.document.settings.preserveLineBreaks))if(segment.faceId)faceIds.add(segment.faceId);
  for(const faceId of faceIds)refs.set(`cq-face:${faceId}`,{id:`cq-face:${faceId}`,mime:"image/png",sourceUrl:`/api/editor/cq-face/${encodeURIComponent(faceId)}`,external:true});
  await resolvePool([...refs.values()],async ref=>{assetData[ref.id]=await resolveAsset(ref)});
  const avatarData:Record<string,string>={};
  await resolvePool(archive.document.characters,async character=>{avatarData[character.id]=await resolveAvatar(character)});
  const characters=archive.document.characters.map(character=>{const palette=storyPalette(character.paletteId),bubble=storyPalette(character.bubblePaletteId||character.paletteId);return{id:character.id,name:character.name,account:character.imUserId,position:character.position,isNarrator:character.isNarrator,narratorAvatar:character.narratorAvatar,color:safeColor(character.color,"#78938f"),avatar:avatarData[character.id]||"",nameDark:safeColor(palette?.nameDark||character.color,"#8fd0c8"),nameLight:safeColor(palette?.nameLight||character.color,"#356c67"),bubbleDark:safeColor(bubble?.bubbleDark,"#182120"),bubbleLight:safeColor(bubble?.bubbleLight,"#f4f7f6"),textDark:safeColor(bubble?.textDark,"#ffffff"),textLight:safeColor(bubble?.textLight,"#17201f")}});
  const messages=archive.document.messages.map(message=>({id:message.id,characterId:message.characterId,kind:message.kind,text:message.kind==="text"?message.text:"",caption:message.kind==="audio"?message.caption||"":"",alt:message.kind==="image"?message.alt||"图片":"",assetId:message.kind!=="text"?message.asset.id:"",replyToId:message.replyToId||"",performance:message.performance||{},segments:message.kind==="text"?storyTextSegments(message.text,archive.document.characters,archive.document.settings.preserveLineBreaks).map(segment=>({text:segment.text,faceId:segment.faceId||"",characterId:segment.character?.id||""})):[],tokens:message.kind==="text"?segmentStoryText(storyStreamingText(message.text,archive.document.characters,archive.document.settings.preserveLineBreaks),message.performance?.tokenGroups).map(token=>({text:token.text,delay:message.performance?.tokenDelays?.[token.index]||0})):[]}));
  const missingResources=[...refs.keys()].filter(id=>!assetData[id]);
  const payload={version:2,title:archive.document.title,author:archive.document.author||"",settings:archive.document.settings,characters,messages,effectTracks:archive.document.effectTracks,characterStateEvents:archive.document.characterStateEvents,assets:assetData,vfx:embeddedVfx,missingResources};
  return standaloneDocument(safeJson(payload));
}

